using UnityEngine;
using UnityEngine.UI;

namespace DreamDungeon
{
    public sealed class TrapShopUI : MonoBehaviour
    {
        [SerializeField] private RectTransform safeAreaRoot; [SerializeField] private TrapShopManager shop; [SerializeField] private TrapDatabase database; [SerializeField] private CurrencyManager currency;
        private RectTransform overlay; private Transform content; private Text status; private Text balance;
        public void Configure(RectTransform safe,TrapShopManager manager,TrapDatabase db,CurrencyManager money){safeAreaRoot=safe;shop=manager;database=db;currency=money;}
        private void Awake(){if(safeAreaRoot==null&&GameObject.Find("SafeAreaRoot")!=null)safeAreaRoot=GameObject.Find("SafeAreaRoot").GetComponent<RectTransform>();Build();if(shop!=null)shop.StatusChanged+=SetStatus;if(currency!=null)currency.CurrencyChanged+=UpdateBalance;}
        private void OnDestroy(){if(shop!=null)shop.StatusChanged-=SetStatus;if(currency!=null)currency.CurrencyChanged-=UpdateBalance;}
        public void Open(){if(overlay==null)Build();if(overlay==null)return;overlay.gameObject.SetActive(true);Refresh();UpdateBalance(currency.Gold,currency.Soul,currency.Crystal);}
        public void Close(){if(overlay!=null)overlay.gameObject.SetActive(false);}
        private void Build(){if(safeAreaRoot==null||overlay!=null)return;overlay=RoomUIFactory.CreateOverlay(safeAreaRoot,"TrapShopPanel");var window=RoomUIFactory.CreateWindow(overlay,"TrapShopWindow",new Vector2(1000,1680),new Color(.075f,.085f,.12f,1));RoomUIFactory.CreateText(window,"TrapShopTitle","TRAP SHOP",38,new Vector2(0,770),new Vector2(760,70),new Color(.96f,.78f,.43f));balance=RoomUIFactory.CreateText(window,"TrapShopBalance","",20,new Vector2(0,700),new Vector2(850,50),Color.white);status=RoomUIFactory.CreateText(window,"TrapShopStatus","Browse traps and buy unlocked traps.",18,new Vector2(0,-755),new Vector2(850,50),new Color(.82f,.85f,.9f));RoomUIFactory.CreateButton(window,"CloseTrapShopButton","CLOSE",new Vector2(405,770),new Vector2(150,68),new Color(.34f,.19f,.19f),19).onClick.AddListener(Close);content=RoomUIFactory.CreateScrollList(window,"TrapShopScroll",new Vector2(0,-20),new Vector2(930,1320));overlay.gameObject.SetActive(false);}
        private void Refresh(){if(content==null||database==null||shop==null)return;for(int i=content.childCount-1;i>=0;i--)Destroy(content.GetChild(i).gameObject);foreach(TrapData data in database.AllTraps){if(data==null)continue;GameObject card=RoomUIFactory.CreateCard(content,"TrapCard_"+data.trapId,240);Transform t=card.transform;var icon=RoomUIFactory.CreatePanel(t,"Icon",data.icon!=null?Color.white:TrapColor(data.trapType),new Vector2(-365,0),new Vector2(90,90));if(data.icon!=null){var img=icon.GetComponent<Image>();img.sprite=data.icon;img.preserveAspect=true;}RoomUIFactory.CreateText(t,"Name",data.trapName,24,new Vector2(-220,82),new Vector2(420,42),Color.white,TextAnchor.MiddleLeft);RoomUIFactory.CreateText(t,"Type",data.trapType.ToString(),17,new Vector2(-220,42),new Vector2(420,36),new Color(.65f,.83f,.72f),TextAnchor.MiddleLeft);string effect=$"DMG {data.damage}   DPS {data.damagePerSecond:0.#}   DURATION {data.duration:0.#}s\nCOOLDOWN {data.cooldown:0.#}s   RADIUS {data.triggerRadius:0.#}   SLOW {data.slowPercentage:P0}";RoomUIFactory.CreateText(t,"Effect",effect,15,new Vector2(-210,-25),new Vector2(470,72),new Color(.85f,.86f,.9f),TextAnchor.MiddleLeft);bool unlocked=shop.DungeonLevel>=data.unlockDungeonLevel;bool can=shop.CanPurchase(data.trapId,out _);RoomUIFactory.CreateText(t,"Unlock",unlocked?$"{data.goldCost} GOLD":"LOCKED • DUNGEON LEVEL "+data.unlockDungeonLevel,16,new Vector2(290,38),new Vector2(220,45),unlocked?new Color(.96f,.78f,.43f):new Color(.9f,.45f,.42f));Button buy=RoomUIFactory.CreateButton(t,"BuyTrapButton",unlocked?(can?"BUY":"UNAVAILABLE"):"LOCKED",new Vector2(335,-55),new Vector2(180,64),new Color(.4f,.27f,.14f),17);buy.interactable=can;buy.onClick.AddListener(()=>Purchase(data.trapId));}Canvas.ForceUpdateCanvases();}
        private void Purchase(string id){if(shop.TryPurchase(id,out string message))SetStatus(message);else SetStatus(message);Refresh();}
        private void UpdateBalance(int gold,int soul,int crystal){if(balance!=null)balance.text=$"GOLD {gold}   SOUL {soul}";}
        private void SetStatus(string value){if(status!=null)status.text=value;}
        private static Color TrapColor(TrapType type)=>type switch{TrapType.Spike=>new Color(.72f,.72f,.74f),TrapType.Fire=>new Color(1f,.3f,.08f),TrapType.Poison=>new Color(.35f,.8f,.2f),TrapType.Slow=>new Color(.25f,.72f,.95f),_=>new Color(.7f,.35f,1f)};
    }
}
